#include "factions/DynamicFactionSystem.h"
#include <algorithm>
namespace subspace {
bool DynamicFactionSystem::Register(const DynamicFactionState& s){if(s.id.empty())return false;states_[s.id]=s;return true;}
FactionStrategicAction DynamicFactionSystem::ChooseAction(const std::string& id,double threat,double scarcity) const {auto it=states_.find(id);if(it==states_.end())return FactionStrategicAction::Recover;auto& s=it->second;if(s.resources<25||s.stability<0.35)return FactionStrategicAction::Recover;if(threat>0.75)return s.military>60?FactionStrategicAction::Patrol:FactionStrategicAction::Fortify;if(scarcity>0.65)return FactionStrategicAction::Mine;if(s.aggression>0.7&&s.military>70)return FactionStrategicAction::Raid;if(s.expansion>0.6&&s.resources>120)return FactionStrategicAction::Expand;if(s.industry>70)return FactionStrategicAction::Trade;return FactionStrategicAction::Research;}
void DynamicFactionSystem::Advance(const std::string& id,FactionStrategicAction a,double h){auto it=states_.find(id);if(it==states_.end()||h<=0)return;auto& s=it->second;switch(a){case FactionStrategicAction::Mine:s.resources+=8*h;s.industry+=0.5*h;break;case FactionStrategicAction::Trade:s.resources+=5*h;s.stability+=0.01*h;break;case FactionStrategicAction::Patrol:s.resources-=2*h;s.military+=0.2*h;break;case FactionStrategicAction::Raid:s.resources+=3*h;s.military-=0.4*h;s.stability-=0.01*h;break;case FactionStrategicAction::Expand:s.resources-=25*h;s.stations+=static_cast<int>(h>=1);break;case FactionStrategicAction::Fortify:s.resources-=8*h;s.military+=2*h;break;case FactionStrategicAction::Research:s.resources-=2*h;s.industry+=1*h;break;case FactionStrategicAction::Recover:s.resources+=2*h;s.stability+=0.04*h;break;}s.stability=std::clamp(s.stability,0.0,1.0);}
const DynamicFactionState* DynamicFactionSystem::Get(const std::string& id) const {auto it=states_.find(id);return it==states_.end()?nullptr:&it->second;}
}
